\caption{MB-by-MB in MPDAG: find local causal structure of a certain node in MPDAG $\mathcal{G}^*$.}
\label{alg:mb-by-mb in MPDAG}
\SetKwInOut{Input}{Input}
\SetKwInOut{Output}{Output}
\small

\Input{A target $X$, observational data $\mathcal{D}$, background knowledge $\mathcal{B}$.}
\Output{A PDAG $G$ containing the local structure of $X$.}
Initialize DoneList $=\emptyset$ (list of nodes whose MBs have been found); \\
Initialize WaitList $=\{X\}$ (list of nodes whose MBs will be found); \\
Initialize $G=(\mathbf{V},\mathcal{B})$ (initial local network around $X$, with known edges in background knowledge). \\
\Repeat{$\mathrm{WaitList\ is\ empty}$}{
Pop a node $Z$ from the head of WaitList and add $Z$ to DoneList; \\
Find $\mathrm{MB}(Z)$ by a variable selection procedure such as IAMB~\citep{tsamardinos2003algorithms}; \\
Learn the marginal graph $L_Z$ over $\mathrm{MB}^+(Z)$ from data $\mathcal{D}$ or directly from learned graph. \\
Put the edges connected to $Z$ and the v-structures containing $Z$ in $L_Z$ to $G.$ \\
\Repeat{$G$ is not changed}{
For $(a\to b- c)\in G,$ if $(a,c,S_{ac})\in $ IndSet and $b\in S_{ac},$ orient $b\to c.$ \\
For $(a\to b\to c - a)\in G,$ orient $a\to c.$ \\
For $a-b,\,a-c\to b$ and $a-d\to b\in G$, if $(c,d,S_{cd})\in$ IndSet and $a\in S_{cd},$ orient $a\to b.$ \\
For $a-b,\,a-c\to b$ and $a-d\to c\in G$, if $(b,d,S_{bd})\in$ IndSet and $a\in S_{bd},$ orient $a\to b.$
}
Update WaitList $=\{U\in \mathbf{V}|U\mathrm{\ and\ }X\mathrm{\ are\ connected\ by\ an\ undirected\ path\ in\ }G\}\ \setminus$ DoneList; \\
}

\Return $G$.

\label{thm:mb-by-mb}
Let $\mathcal{G}^*$ be the MPDAG under background knowledge $\mathcal{B}.$ Let $\mathcal{G}\in [\mathcal{G}^*]$ be the true underlying DAG and $\mathcal{D}$ be i.i.d. observations generated from a distribution Markovian and faithful with respect to $\mathcal{G}.$ Let $X$ be a target node in $\mathcal{G}.$ Suppose all conditional independencies are correctly checked, and let $G$ be the output of MB-by-MB in MPDAG (Algorithm~\ref{alg:mb-by-mb in MPDAG}) with input $X,\mathcal{D},\mathcal{B}$.
Then for each $Z$ connected with $X$ by an undirected path in $\mathcal{G}^*,$ including $X$ itself, we have $pa(Z,G)=pa(Z,\mathcal{G}^*),ch(Z,G)=ch(Z,\mathcal{G}^*),sib(Z,G)=sib(Z,\mathcal{G}^*).$

\label{lemma:identify critical set}
Let $\mathcal{G}^*$ be an MPDAG and $X, Y$ be two distinct nodes in $\mathcal{G}^*.$ Suppose that $X$ is not a definite cause of $Y$ in $\mathcal{G}^*.$ Let $\mathbf{C}$ be the critical set of $X$ with respect to $Y$ in $\mathcal{G}^*.$ Let $\mathcal{Q}$ be the set of all $\mathbf{Q}\subseteq sib(X,\mathcal{G}^*)$ such that orienting $\mathbf{Q}\to X$ and $X\to sib(X,\mathcal{G}^*)\setminus \mathbf{Q}$ does not introduce any v-structure collided on $X$ or any directed triangle containing $X.$ Then we have
$$\cap \left\{ \mathbf{Q}\in \mathcal{Q} \mid X\perp Y \mid pa(X,\mathcal{G}^*)\cup \mathbf{Q} \right\} = an(\mathbf{C},\mathcal{G}^*)\cap sib(X,\mathcal{G}^*).$$

