\caption{Learning the local structure around $X$ given background knowledge consisting of direct causal information $\mathcal{B}_1$ and non-ancestral information $\mathcal{B}_2$.}
\label{alg:local struct:direct and non-an}
\SetKwInOut{Input}{Input}
\SetKwInOut{Output}{Output}
\small

\Input{Target node $X$, observational data $\mathcal{D}$, background knowledge $\mathcal{B}=\mathcal{B}_1\cup \mathcal{B}_2$.}
\Output{A PDAG $G$ containing the local structure of $X$.}
Let $G$ be the output of Algorithm~\ref{alg:mb-by-mb in MPDAG} under input $X,\mathcal{D},\mathcal{B}_1$.

\ForEach{$(N_j,T_j)\in \mathcal{B}_2$}{
\If{$N_j$ and $X$ are connected by an undirected path in $G$}{
Let $\mathbf{candC} = sib(N_j,G).$

\ForEach{$\mathbf{Q}\subseteq sib(N_j,G)$ such that orienting $\mathbf{Q}\to N_j$ does not introduce any v-structure collided on $N_j$ or any directed triangle containing $N_j$}{
\If{$N_j \perp T_j \mid pa(N_j,G)\cup \mathbf{Q}$}{
	Update $\mathbf{candC}:=\mathbf{candC}\cap \mathbf{Q}.$
}
}
Orient $\mathbf{candC}\to N_j$ and apply Meek's rules on $G.$
}
}
\Return $G$.

\label{thm:correct alg non-an}
Let $\mathcal{G}^*$ be the MPDAG under background knowledge $\mathcal{B}$ consisting of direct causal information $\mathcal{B}_1$ and non-ancestral information $\mathcal{B}_2.$ Let $\mathcal{G}\in [\mathcal{G}^*]$ be the true underlying DAG and $\mathcal{D}$ be i.i.d. observations generated from a distribution Markovian and faithful with respect to $\mathcal{G}.$ Let $X$ be a target node in $\mathcal{G}.$ Suppose all conditional independencies are correctly checked, and let $G$ be the output of Algorithm~\ref{alg:local struct:direct and non-an} with input $X,\mathcal{D},\mathcal{B}$.
Then for each $Z$ connected with $X$ by an undirected path in $\mathcal{G}^*,$ including $X$ itself, we have $pa(Z,G)=pa(Z,\mathcal{G}^*),ch(Z,G)=ch(Z,\mathcal{G}^*),sib(Z,G)=sib(Z,\mathcal{G}^*).$

