\caption{Check the consistency of a DEGS corresponding to an MPDAG.}
\label{alg:check DEGS}
\SetKwInOut{Input}{Input}
\SetKwInOut{Output}{Output}
\small

\Input{An MPDAG $M=(V,E_M)$, a DEGS $S=\langle (d_1,p_1,r_1),\dots,(d_k,p_k,r_k) \rangle$, a set of background knowledge $B\subset E_M$}
\Output{A bool variable indicates whether $S$ is consistent with $M,B$.}

$H$ = the skeleton of $M;$ ($H=(V,E_H)$ is a PDAG) \\
\ForEach{$i$ in $\{1,2,\dots,k\}$}{
\If{$p_i \not\subset E_H$ or $d_i\in E_H$}{
\Return FALSE;
}
\Switch{$r_i$}{
\uCase{"V"}{
\uIf{$p_i\neq \emptyset$ or $d_i$ is not contained in a v-structure of $M$}{\Return FALSE;}
}
\uCase{"B"}{
\uIf{$p_i\neq \emptyset$ or $d_i\not\in B$}{\Return FALSE;}
}
\uCase{"R1"}{
Find $a,b,c\in V$ such that $a\to b-c\in H,$ $d_i=b\to c, p_i=\{a\to b\}$ and $a,c$ are not adjacent in $H$. \\
\uIf{such $a,b,c$ does not exist}{\Return FALSE;}
}
\uCase{"R2"}{
Find $a,b,c\in V$ such that $a\to b\to c\in H,a-c\in H,d_i=a\to c,p_i=\{a\to b,b\to c\}.$ \\
\uIf{such $a,b,c$ does not exist}{\Return FALSE;}
}
\uCase{"R3"}{
Find $a,b,c,d\in V$ such that $b-a-c\in H,b\to d\leftarrow c\in H,a-d\in H,d_i=a\to d,p_i=\{b\to d,c\to d\},$ and $(b,a,c)$ is not a v-structure in $M.$ \\
\uIf{such $a,b,c,d$ does not exist}{\Return FALSE;}
}
\uCase{"R4"}{
Find $a,b,c,d\in V$ such that $b-a-c\in H,c\to d\to b\in H,a-d\in H,d_i=a\to b,p_i=\{c\to d\},$ and $(b,a,c)$ is not a v-structure in $M.$ \\
\uIf{such $a,b,c,d$ does not exist}{\Return FALSE;}
}
}
Add $d_i$ to $E_H.$
}
\If{$H\neq M$}{\Return FALSE;}
\Return TRUE;

