\caption{Learning the local structure around $X$ given background knowledge consisting of direct causal information $\mathcal{B}_1$, non-ancestral information $\mathcal{B}_2$ and ancestral information $\mathcal{B}_3$.}
\label{alg:local struct:all types}
\SetKwInOut{Input}{Input}
\SetKwInOut{Output}{Output}
\small

\Input{Target node $X$, observational data $\mathcal{D}$, background knowledge $\mathcal{B}=\mathcal{B}_1\cup \mathcal{B}_2\cup \mathcal{B}_3$.}
\Output{A PDAG $G$ containing the local structure of $X$ and a set of direct causal clauses within $G$.}
Let $G$ be the output of MB-by-MB algorithm~\citep{wang2014discovering} under input $X,\mathcal{D},\mathcal{B}_1$.

Let $\mathrm{DCC}=\emptyset$.

\ForEach{$(F_j,T_j)\in \mathcal{B}_3$}{
\If{$F_j$ and $X$ are connected by an undirected path in $G$}{
Let $\mathbf{candC} = sib(N_j,G), \mathrm{hasCand}=\mathrm{FALSE}.$

Let $\mathcal{Q}$ be the set of all maximal cliques in the induced subgraph of $G$ over $sib(N_j,G)$.

Let $\mathcal{Q}_1$ be the set of all $\mathbf{Q}\subseteq sib(F_j,G)$ such that letting $\mathbf{Q}\to F_j$ and $F_j\to sib(F_j,G)\setminus \mathbf{Q}$ does not introduce any v-structure collided on $F_j$.

\ForEach{$\mathbf{Q}\in \mathcal{Q}$}{
\If{$F_j \perp T_j \mid pa(F_j,G)\cup \mathbf{Q}$}{
Update $\mathbf{candC}:=\mathbf{candC}\cap \mathbf{Q}.$

Update $\mathrm{hasCand}:=\mathrm{TRUE}.$
}
}
\If{$\mathrm{hasCand}$}{
\ForEach{$\mathbf{Q}\in \mathcal{Q}_1\setminus \mathcal{Q}$}{
\If{$F_j \perp T_j \mid pa(F_j,G)\cup \mathbf{Q}$}{
Update $\mathbf{candC}:=\mathbf{candC}\cap \mathbf{Q}.$
}
}
Add $F_j \overset{or}{\to} \mathbf{candC}$ into $\mathrm{DCC}$.
}
}
}

\ForEach{$(F_i,T_i)\in \mathcal{B}_1$}{
\If{$F_j$ and $X$ are connected by an undirected path in $G$}{
Orient $F_i\to T_i$ and apply Meek's rules on $G$.
}
}

Run Step 2 to 12 of Algorithm~\ref{alg:local struct:direct and non-an}.

\Return{G, DCC}
